        '<b>D&A와 CAPEX의 시차가 하강기 FCF를 떠받친다.</b> D&A(감가상각·무형자산상각)는 재무제표에 별도 항목이 없어 반도체 설비 내용연수 약 4년을 전제로 직전 4개년 CAPEX 평균으로 근사했다. 그래서 2030년엔 D&A 768,178억 원이 그 해 CAPEX 650,000억 원보다 커진다. 상승기에 사둔 장비값이 뒤늦게 상각으로 잡히는데 정작 불황 저점엔 신규 투자를 줄이기 때문이다. FCF는 D&A를 더하고 CAPEX를 빼므로 이 구간 현금흐름이 오히려 좋아진다.',
        '<b>필자 자신이 역산으로 자기 값을 검증한다.</b> 영구성장률 2.5%를 고정하고 시장가 255,250원을 정당화하는 할인율을 되돌리면 16.2%가 나온다. 자기가 쓴 WACC 10.34%보다 5.9%p 높다. 필자는 "썩 현실적이지 않다"고 적는다.',
